--
-- Table structure for table `returns`
--

DROP TABLE IF EXISTS `returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `returns` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `order_id` int unsigned NOT NULL,
  `vendor_id` int unsigned NOT NULL,
  `return_type` enum('RETURN','REPLACEMENT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('REQUESTED','VENDOR_REVIEW','APPROVED','REJECTED','PICKUP_SCHEDULED','RETURN_PICKED_UP','RETURN_COMPLETED','REPLACEMENT_SHIPPED','REPLACEMENT_DELIVERED','REFUNDED','SENT_TO_DELIVERY') COLLATE utf8mb4_unicode_ci DEFAULT 'REQUESTED',
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `vendor_rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `delivery_request_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `order_id` (`order_id`),
  KEY `vendor_id` (`vendor_id`),
  CONSTRAINT `returns_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `returns_ibfk_2` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `returns_ibfk_3` FOREIGN KEY (`vendor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `returns_chk_1` CHECK (json_valid(`images`))
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
