--
-- Table structure for table `variants`
--

DROP TABLE IF EXISTS `variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `variants` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `model_id` int unsigned NOT NULL,
  `sku` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `barcode` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `mrp` decimal(10,2) NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `status` enum('DRAFT','PENDING','PUBLISHED','OUT_OF_STOCK') COLLATE utf8mb4_general_ci DEFAULT 'PUBLISHED',
  `attributes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci,
  `highlights` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `warranty` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `whats_in_the_box` text COLLATE utf8mb4_general_ci,
  `specifications` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `public_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `return_policy` enum('NO_RETURN','REPLACEMENT_ONLY','REFUND_ONLY','REPLACEMENT_AND_REFUND') COLLATE utf8mb4_general_ci DEFAULT 'NO_RETURN',
  `return_window_days` int DEFAULT '7',
  `seo_slug` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sku` (`sku`),
  UNIQUE KEY `public_id` (`public_id`),
  UNIQUE KEY `seo_slug` (`seo_slug`),
  KEY `model_id` (`model_id`),
  CONSTRAINT `variants_ibfk_1` FOREIGN KEY (`model_id`) REFERENCES `models` (`id`) ON DELETE CASCADE,
  CONSTRAINT `variants_chk_1` CHECK (json_valid(`attributes`)),
  CONSTRAINT `variants_chk_2` CHECK (json_valid(`highlights`)),
  CONSTRAINT `variants_chk_3` CHECK (json_valid(`specifications`))
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `variants`
--

LOCK TABLES `variants` WRITE;
/*!40000 ALTER TABLE `variants` DISABLE KEYS */;
INSERT INTO `variants` VALUES (60,25,'GEN-T-S-POL-975-AMAZONBRANDSYMBOLMENSCOTTONRICHSOLIDPOLOTSHIRTCOLLARTSHIRTSHALFSLEEVESPLAINREGULA-60',NULL,599.00,699.00,12,'PUBLISHED','{\"Size\":\"S\",\"Color\":\"Pink\",\"title\":\"Amazon Brand - Symbol Men\'s Cotton Rich Solid Polo Tshirt | Collar Tshirts | Half Sleeves | Plain-Regular Fit (Available in Plus Sizes and Combo Pack of 2)\",\"Pack of\":\"Pack of 1\"}','2026-08-05 10:13:03','2026-08-14 13:55:24','Amazon Brand - Symbol Men\'s Cotton Rich Solid Polo Tshirt | Collar Tshirts | Half Sleeves | Plain-Regular Fit (Available in Plus Sizes and Combo Pack of 2)','FABRIC: Cotton-polyester blend for perfect shape retention and easy maintenance.','[]','No Warranty','T-shirt','\"{\\\"Pattern\\\": \\\"Solid\\\", \\\"Fit type\\\": \\\"Regular Fit\\\", \\\"Sleeve type\\\": \\\"Short Sleeve\\\", \\\"Collar style\\\": \\\"Classic Collar\\\"}\"','VART3AYJE6J','NO_RETURN',7,'gen-t-s-pol-975-amazonbrandsymbolmenscottonrichsolidpolotshirtcollartshirtshalfsleevesplainregula-60'),(73,25,'GEN-T-S-POL-975-AMAZONBRANDSYMBOLMENSCOTTONRICHSOLIDPOLOTSHIRTCOLLARTSHIRTSHALFSLEEVESPLAINREGULA-73',NULL,499.00,699.00,17,'PUBLISHED','{\"Size\":\"S\",\"Color\":\"Blue\",\"title\":\"Amazon Brand - Symbol Men\'s Cotton Rich Solid Polo Tshirt | Collar Tshirts | Half Sleeves | Plain-Regular Fit (Available in Plus Sizes and Combo Pack of 2)\"}','2026-08-05 10:57:34','2026-08-15 04:35:07','Amazon Brand - Symbol Men\'s Cotton Rich Solid Polo Tshirt | Collar Tshirts | Half Sleeves | Plain-Regular Fit (Available in Plus Sizes and Combo Pack of 2)','FABRIC: Cotton-polyester blend for perfect shape retention and easy maintenance.\n','[]','No Warranty','T-shirt','\"{\\\"Fit type\\\": \\\"Regular Fit\\\", \\\"Sleeve type\\\": \\\"Short Sleeve\\\", \\\"Collar style\\\": \\\"Polo Collar\\\", \\\"Material composition\\\": \\\"60% Cotton, 40% Polyester\\\"}\"','VARVXESFB6Y','NO_RETURN',7,'gen-t-s-pol-975-amazonbrandsymbolmenscottonrichsolidpolotshirtcollartshirtshalfsl